const quitarExtension = `-- name: QuitarExtension :one
UPDATE mensajeria.centralita_extensiones SET activa = false, quitada_en = $1::timestamptz, updated_at = now()
WHERE id = $2 AND activa
RETURNING id, empresa_id, centralita_id, extension, usuario_id, tipo, sip_usuario, sip_secreto_cifrado, activa, quitada_en, created_at, updated_at
`

type QuitarExtensionParams struct {
	Ahora time.Time
	ID    int64
}

func (q *Queries) QuitarExtension(ctx context.Context, arg QuitarExtensionParams) (MensajeriaCentralitaExtensione, error) {
	row := q.db.QueryRow(ctx, quitarExtension, arg.Ahora, arg.ID)
	var i MensajeriaCentralitaExtensione
	err := row.Scan(
		&i.ID,
		&i.EmpresaID,
		&i.CentralitaID,
		&i.Extension,
		&i.UsuarioID,
		&i.Tipo,
		&i.SipUsuario,
		&i.SipSecretoCifrado,
		&i.Activa,
		&i.QuitadaEn,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

const receptoresCentralita = `-- name: ReceptoresCentralita :many
SELECT r.usuario_id, r.extension, u.nombre FROM mensajeria.centralita_receptores r
JOIN nucleo.usuarios u ON u.id = r.usuario_id
WHERE r.llamada_id = $1 ORDER BY r.extension
`

type ReceptoresCentralitaRow struct {
	UsuarioID int64
	Extension string
	Nombre    string
}

func (q *Queries) ReceptoresCentralita(ctx context.Context, llamadaID uuid.UUID) ([]ReceptoresCentralitaRow, error) {
	rows, err := q.db.Query(ctx, receptoresCentralita, llamadaID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ReceptoresCentralitaRow
	for rows.Next() {
		var i ReceptoresCentralitaRow
		if err := rows.Scan(&i.UsuarioID, &i.Extension, &i.Nombre); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

