const soltarMotorCentralita = `-- name: SoltarMotorCentralita :exec
UPDATE mensajeria.centralitas SET motor_dueno = NULL, motor_hasta = NULL WHERE id = $1 AND motor_dueno = $2
`

type SoltarMotorCentralitaParams struct {
	ID    int64
	Dueno *string
}

func (q *Queries) SoltarMotorCentralita(ctx context.Context, arg SoltarMotorCentralitaParams) error {
	_, err := q.db.Exec(ctx, soltarMotorCentralita, arg.ID, arg.Dueno)
	return err
}

const tieneExtensionActiva = `-- name: TieneExtensionActiva :one
SELECT EXISTS (
    SELECT 1 FROM mensajeria.centralita_extensiones x
    JOIN mensajeria.centralitas c ON c.id = x.centralita_id
    WHERE x.usuario_id = $1::bigint AND x.activa AND c.activa AND coalesce(c.empresa_id, 0) = $2::bigint
)::boolean AS tiene
`

type TieneExtensionActivaParams struct {
	Usuario int64
	Empresa int64
}

// El usuario tiene una extensión activa en la centralita activa de la empresa (feed de la ventana).
func (q *Queries) TieneExtensionActiva(ctx context.Context, arg TieneExtensionActivaParams) (bool, error) {
	row := q.db.QueryRow(ctx, tieneExtensionActiva, arg.Usuario, arg.Empresa)
	var tiene bool
	err := row.Scan(&tiene)
	return tiene, err
}

const tocarCentralita = `-- name: TocarCentralita :exec
UPDATE mensajeria.centralitas SET ultimo_evento_en = $1
WHERE id = $2 AND (ultimo_evento_en IS NULL OR ultimo_evento_en < $3::timestamptz)
`

type TocarCentralitaParams struct {
	Ahora      *time.Time
	ID         int64
	HaceMinuto time.Time
}

// Señal de vida del AMI: como mucho una escritura por minuto.
func (q *Queries) TocarCentralita(ctx context.Context, arg TocarCentralitaParams) error {
	_, err := q.db.Exec(ctx, tocarCentralita, arg.Ahora, arg.ID, arg.HaceMinuto)
	return err
}

const tomarMotorCentralita = `-- name: TomarMotorCentralita :one
UPDATE mensajeria.centralitas SET motor_dueno = $1, motor_hasta = now() + make_interval(secs => $2::int)
WHERE id = $3 AND activa AND (motor_dueno IS NULL OR motor_dueno = $1 OR motor_hasta < now())
RETURNING id
`

type TomarMotorCentralitaParams struct {
	Dueno    *string
	Segundos int32
	ID       int64
}

// El arriendo de la conexión: lo toma quien no tiene dueño, quien ya lo tenía o si venció.
func (q *Queries) TomarMotorCentralita(ctx context.Context, arg TomarMotorCentralitaParams) (int64, error) {
	row := q.db.QueryRow(ctx, tomarMotorCentralita, arg.Dueno, arg.Segundos, arg.ID)
	var id int64
	err := row.Scan(&id)
	return id, err
}

const usuarioDeEmpresaActivo = `-- name: UsuarioDeEmpresaActivo :one
SELECT u.id, u.nombre FROM nucleo.usuarios u
WHERE u.id = $1::bigint AND u.activo AND u.tipo = 'persona'
  AND ($2::bigint = 0
       OR EXISTS (SELECT 1 FROM nucleo.usuarios_empresas ue WHERE ue.usuario_id = u.id AND ue.empresa_id = $2::bigint)
       OR EXISTS (SELECT 1 FROM nucleo.usuarios_roles ur JOIN nucleo.roles r ON r.id = ur.rol_id AND r.activo
                  JOIN nucleo.roles_permisos rp ON rp.rol_id = ur.rol_id
                  WHERE ur.usuario_id = u.id AND rp.permiso = 'empresas.todas' AND ur.zona_id IS NULL AND ur.cuadrilla_id IS NULL))
`

type UsuarioDeEmpresaActivoParams struct {
	Usuario int64
	Empresa int64
}

type UsuarioDeEmpresaActivoRow struct {
	ID     int64
	Nombre string
}

// El usuario existe, está activo y pertenece a la empresa (o la empresa es 0: sin multiempresa).
func (q *Queries) UsuarioDeEmpresaActivo(ctx context.Context, arg UsuarioDeEmpresaActivoParams) (UsuarioDeEmpresaActivoRow, error) {
	row := q.db.QueryRow(ctx, usuarioDeEmpresaActivo, arg.Usuario, arg.Empresa)
	var i UsuarioDeEmpresaActivoRow
	err := row.Scan(&i.ID, &i.Nombre)
	return i, err
}
